create extension if not exists pgcrypto;
create table if not exists profiles(user_id uuid primary key references auth.users(id) on delete cascade,role text not null check(role in('manager','admin')),display_name text);
create table if not exists order_rounds(id uuid primary key default gen_random_uuid(),restaurant_name text not null,restaurant_phone text,access_code text not null unique,deadline timestamptz not null,delivery_time timestamptz,status text not null default 'draft' check(status in('draft','open','closed','ordered','delivered','cancelled')),created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists menu_items(id uuid primary key default gen_random_uuid(),round_id uuid not null references order_rounds(id) on delete cascade,item_number text,name text not null,description text,category text not null,price numeric(8,2) not null check(price>=0),vegetarian boolean default false,vegan boolean default false,available boolean default true);
create table if not exists orders(id uuid primary key default gen_random_uuid(),round_id uuid not null references order_rounds(id) on delete cascade,participant_name text not null,edit_token_hash text not null,note text,status text default 'submitted',total_amount numeric(8,2) default 0,paid boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,menu_item_id uuid not null references menu_items(id),item_number text,item_name text not null,quantity int not null check(quantity between 1 and 20),unit_price numeric(8,2) not null,spice text,side text,note text);
create or replace function is_manager() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where user_id=auth.uid() and role in('manager','admin'))$$;
alter table profiles enable row level security;alter table order_rounds enable row level security;alter table menu_items enable row level security;alter table orders enable row level security;alter table order_items enable row level security;
revoke all on profiles,order_rounds,menu_items,orders,order_items from anon,authenticated;
grant select on order_rounds,menu_items to anon,authenticated;grant select,insert,update,delete on order_rounds,menu_items,orders,order_items to authenticated;grant select on profiles to authenticated;
create policy manager_profiles on profiles for select to authenticated using(is_manager());
create policy public_open_round on order_rounds for select to anon,authenticated using(status='open' and deadline>now() or is_manager());
create policy manager_rounds on order_rounds for all to authenticated using(is_manager()) with check(is_manager());
create policy public_menu on menu_items for select to anon,authenticated using(exists(select 1 from order_rounds r where r.id=round_id and r.status='open' and r.deadline>now()) or is_manager());
create policy manager_menu on menu_items for all to authenticated using(is_manager()) with check(is_manager());
create policy manager_orders on orders for all to authenticated using(is_manager()) with check(is_manager());
create policy manager_items on order_items for all to authenticated using(is_manager()) with check(is_manager());
create or replace function get_active_round(p_code text) returns table(id uuid,restaurant_name text,restaurant_phone text,deadline timestamptz,delivery_time timestamptz,status text) language sql security definer set search_path=public as $$select r.id,r.restaurant_name,r.restaurant_phone,r.deadline,r.delivery_time,r.status from order_rounds r where r.access_code=p_code and r.status='open' and r.deadline>now() limit 1$$;
revoke all on function get_active_round(text) from public;grant execute on function get_active_round(text) to anon,authenticated;
create or replace function submit_lunch_order(p_round_code text,p_participant_name text,p_edit_token text,p_note text,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare v_round uuid;v_order uuid;v_total numeric:=0;v jsonb;m menu_items%rowtype;begin if length(trim(p_participant_name))<2 then raise exception 'Name ist zu kurz';end if;if jsonb_array_length(p_items)<1 or jsonb_array_length(p_items)>20 then raise exception 'Ungültige Anzahl Positionen';end if;select id into v_round from order_rounds where access_code=p_round_code and status='open' and deadline>now() for update;if v_round is null then raise exception 'Bestellrunde ungültig oder geschlossen';end if;insert into orders(round_id,participant_name,edit_token_hash,note) values(v_round,left(trim(p_participant_name),80),crypt(p_edit_token,gen_salt('bf')),left(p_note,500)) returning id into v_order;for v in select * from jsonb_array_elements(p_items) loop select * into m from menu_items where id=(v->>'menu_item_id')::uuid and round_id=v_round and available=true;if m.id is null then raise exception 'Gericht nicht verfügbar';end if;if (v->>'quantity')::int not between 1 and 20 then raise exception 'Ungültige Menge';end if;insert into order_items(order_id,menu_item_id,item_number,item_name,quantity,unit_price,spice,side,note) values(v_order,m.id,m.item_number,m.name,(v->>'quantity')::int,m.price,left(v->>'spice',30),left(v->>'side',50),left(v->>'note',250));v_total:=v_total+m.price*(v->>'quantity')::int;end loop;update orders set total_amount=v_total where id=v_order;return v_order;end$$;
revoke all on function submit_lunch_order(text,text,text,text,jsonb) from public;grant execute on function submit_lunch_order(text,text,text,text,jsonb) to anon,authenticated;
